bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const r=await pool.query("SELECT to_regclass('videobot_owner_update_jobs') IS NOT NULL AS jobs,to_regclass('videobot_creator_sessions') IS NOT NULL AS sessions,to_regclass('videobot_webhook_updates') IS NOT NULL AS webhook");
 console.log('SCHEMA',JSON.stringify(r.rows[0]));
 console.log('OWNER_JOBS_ENV',process.env.VIDEOBOT_OWNER_JOBS==='YES');
 if(!r.rows[0].jobs){process.exit(76);}
 const c=await pool.query("SELECT column_name FROM information_schema.columns WHERE table_name='videobot_owner_update_jobs' ORDER BY ordinal_position");
 console.log('COLUMNS',JSON.stringify(c.rows));
 const q=await pool.query("SELECT status,count(*)::int AS n FROM videobot_owner_update_jobs WHERE owner_id=$1 GROUP BY status",[(await pool.query("SELECT seller_user_id FROM videobot_listings WHERE listing_id='v26nov24invoice'")).rows[0]?.seller_user_id]);
 console.log('OWNER_COUNTS',JSON.stringify(q.rows));
 const m=await pool.query("SELECT count(*)::int AS n FROM videobot_owner_update_jobs WHERE owner_id=$1 AND status='queued' AND ((payload->'callback_query'->>'data') LIKE 'menu:%' OR (payload->'message'->>'text') LIKE '/start%')",[(await pool.query("SELECT seller_user_id FROM videobot_listings WHERE listing_id='v26nov24invoice'")).rows[0]?.seller_user_id]);
 console.log('MENU_QUEUED',m.rows[0].n);
 if(q.rows.some(x=>x.status==='needs_reconcile')&&m.rows[0].n>0)process.exitCode=73;
 else if(q.rows.some(x=>x.status==='needs_reconcile'))process.exitCode=74;
}catch(e){console.log('DB_ERROR_CODE',e.code??'unknown');process.exitCode=e.code==='42P01'?76:e.code==='42703'?77:79;}
finally{await pool.end()}
JS
